$root=dirname(getenv('KH_NATIVE_TEST_CONFIG')).'/sections-media';$media=new Media($db,$access,$root);$image=imagecreatetruecolor(20,12);imagepng($image,$root.'/source.png');unset($image);$photo=$media->upload($root.'/source.png','source.png','Original media alt');$bytes=hash_file('sha256',$media->variant($photo['id'],'original')['path']);
$row=['id'=>bin2hex(random_bytes(16)),'heading'=>'Website section 🎶','body_html'=>'<p>Section-only needle <strong>original</strong><script>bad()</script></p>','media_id'=>$photo['id'],'alt'=>'Authored original alt','caption'=>'Original caption <&>','credit'=>'Private author <&>','layout'=>'image-before','button_label'=>'Own website','button_url'=>'/site/contact#address'];
$plain=['id'=>bin2hex(random_bytes(16)),'heading'=>'Second section','body_html'=>'<p>Second original</p>','media_id'=>null,'layout'=>'text'];$sections=ContentSections::normalize([$row,$plain]);
check(!str_contains($sections[0]['body_html'],'script')&&str_contains($sections[0]['body_html'],'<strong>original</strong>'),'section rich text is sanitized while authored formatting remains');
$source=$pages->save(['title'=>'Original page','slug'=>'sections-original','body_html'=>'<p>Original page &amp; 0</p>','excerpt'=>'Original intro','nav_visible'=>false]);$source=$pages->publish($source['id'],$source['version']);$public=$pages->publicPage($source['slug']);$generation=$pages->generation();$history=$pages->revisions($source['id']);
$saved=$service->save($source['id'],$source['version'],$sections);
check($saved['id']===$source['id']&&$saved['version']===$source['version']+1&&$saved['content_sections']===$sections,'section collection binds to existing page identity and exactly one private revision');
foreach(['body','body_html','title','slug','excerpt','media_ids','gallery_items','template_definition','field_definitions','custom_fields']as $key)check($saved[$key]===$source[$key],'unrelated page original retained: '.$key);
check($pages->publicPage($source['slug'])===$public&&$pages->generation()===$generation,'private sections do not replace publication or invalidate public generation');
check(array_slice($pages->revisions($source['id']),1)===$history,'all earlier exact revisions retained');
check($media->publicVariant($photo['id'],'medium')===null,'section-only private image is not publicly exposed');
check($pages->count([['field'=>'search_text','op'=>'contains','value'=>'Section-only needle']])===1,'bounded SQL editor search includes derived section text');
check($service->save($saved['id'],$saved['version'],$sections)===$saved,'identical section collection creates no extra revision');
