$published=$pages->publish($saved['id'],$saved['version']);
check($media->publicVariant($photo['id'],'medium')!==null,'explicit publication projects section-only media references');
$site=new Site($pages,$media,new Cache($root.'/cache'),'https://example.invalid',$access->club());$html=$site->page($source['slug']);
check(str_contains($html,'website-content-section--image-before')&&str_contains($html,'/media/'.$photo['id'].'/medium')&&str_contains($html,'Original caption &lt;&amp;&gt;'),'public renderer uses exact published layouts, authored captions and references');
check(count((new Feeds($pages,'https://example.invalid'))->search('Section-only needle'))===1,'public search includes only original published section text');
$changed=$service->save($published['id'],$published['version'],array_reverse($sections));
check($site->page($source['slug'])===$html&&$pages->publicPage($source['slug'])['content_sections']===$sections,'private reorder leaves actual cached public HTML and section original unchanged');
$copy=(new PageCopies($db,$access))->create($changed['id'],$changed['version'],['title'=>'Copied sections','slug'=>'sections-copy']);
check($copy['content_sections']===array_reverse($sections)&&$copy['published_revision']===null,'private page copy retains exact section IDs, ordering and authored metadata');
$restored=$pages->restore($changed['id'],$published['version'],$changed['version']);
check($restored['content_sections']===$sections&&$site->page($source['slug'])===$html,'historical restore returns collection as a new private revision');
$comparison=VersionChanges::between($published,$changed);$difference=array_values(array_filter($comparison,fn($c)=>$c['key']==='content_sections'));
check(count($difference)===1&&$difference[0]['before']['type']==='content-sections','version comparison treats ordered section collection as original domain value');
check(str_contains((new VersionValues($db,$access))->render($difference[0]['before']),'Authored original alt'),'historical section comparison shows original image description and credit');
$post=[];foreach($sections as $index=>$value){$value['media_id']??='';$post[]=$value+['position'=>(string)(20-$index*10)];}
check(ContentSectionsPanel::fromPost(['section_rows'=>$post,'section_row_count'=>'2'])===array_reverse($sections),'normal form explicitly reorders exact originals');
$post[0]['remove']='1';check(ContentSectionsPanel::fromPost(['section_rows'=>$post,'section_row_count'=>'2'])===[$sections[1]],'explicit remove leaves other original section intact');
$post[1]['remove']='1';check(ContentSectionsPanel::fromPost(['section_rows'=>$post,'section_row_count'=>'2'])===[],'normal form can explicitly empty collection');
$proposal=$post;foreach($proposal as &$value)unset($value['remove']);unset($value);$proposal[0]['button_label']='Proposed link';$proposal[0]['button_url']='javascript:alert(1)';
$_SERVER['REQUEST_METHOD']='POST';$_POST=['csrf'=>'csrf','operation'=>'page-sections-save','id'=>$restored['id'],'version'=>(string)$source['version'],'section_row_count'=>'2','section_rows'=>$proposal];http_response_code(422);
$form=(new ContentSectionsPanel($db,$access,'csrf'))->render($restored);
check(str_contains($form,'value="javascript:alert(1)"')&&!str_contains($form,'href="javascript:'),'invalid proposed link retained safely as editable input');
check(str_contains($form,'name="version" value="'.$source['version'].'"'),'invalid form retains its originally submitted page version');
$_POST['csrf']='wrong';$_POST['operation']='page-save';$unsafe=(new ContentSectionsPanel($db,$access,'csrf'))->render($restored,true);
check(!str_contains($unsafe,'value="javascript:alert(1)"')&&str_contains($unsafe,'value="Website section 🎶"'),'invalid CSRF cannot restore old sections into a current embedded page form');
$_POST['csrf']='csrf';$unsafe=(new ContentSectionsPanel($db,$access,'csrf'))->render($restored,true);
check(!str_contains($unsafe,'value="javascript:alert(1)"'),'embedded recovery cannot attach older sections to a newer page version');
$_POST=[];$_SERVER['REQUEST_METHOD']='GET';http_response_code(200);
rejects(fn()=>ContentSectionsPanel::fromPost(['section_rows'=>$post,'section_row_count'=>'3']),InvalidArgumentException::class,'truncated whole collection cannot remove unseen originals');
$partial=$post;unset($partial[0]['heading']);rejects(fn()=>ContentSectionsPanel::fromPost(['section_rows'=>$partial,'section_row_count'=>'2']),InvalidArgumentException::class,'truncated section fields cannot silently clear originals');
$twenty=[];for($i=0;$i<20;++$i)$twenty[]=array_replace($plain,['id'=>bin2hex(random_bytes(16))]);check(count(ContentSections::normalize($twenty))===20,'actual maximum 20 distinct website sections accepted');
foreach(['https://example.invalid/contact','/site/contact#address','#address']as $url)check(ContentSections::normalize([array_replace($row,['button_url'=>$url])])[0]['button_url']===$url,'safe absolute, own-path and anchor section links retained');
foreach([array_fill(0,21,$plain),[$plain,$plain],[array_replace($row,['alt'=>''])],[array_replace($row,['media_id'=>null])],[array_replace($plain,['layout'=>'other'])],[array_replace($plain,['heading'=>[]])],[array_replace($plain,['unknown'=>'forged'])]]as $input)rejects(fn()=>ContentSections::normalize($input),InvalidArgumentException::class,'malformed, duplicate, oversized or inconsistent section rejected');
foreach(['javascript:alert(1)','//elsewhere.invalid','/\\elsewhere.invalid','https://user:password@example.invalid/','/bad%0aLocation:foo']as $url)rejects(fn()=>ContentSections::normalize([array_replace($row,['button_url'=>$url])]),InvalidArgumentException::class,'unsafe section button URL rejected');
$foreign=new Media($db,new Access($db,'outsider'),$root.'/other');$foreignPhoto=$foreign->upload($root.'/source.png','foreign.png','Foreign alt');
rejects(fn()=>$service->save($restored['id'],$restored['version'],[array_replace($sections[0],['media_id'=>$foreignPhoto['id']])]),InvalidArgumentException::class,'foreign section media reference rejected atomically');
rejects(fn()=>(new PageSections($db,new Access($db,'reader')))->save($restored['id'],$restored['version'],[]),DomainException::class,'read-only role cannot replace sections');
$news=$pages->save(['title'=>'Original news','slug'=>'sections-news','template'=>'news','news_date'=>'2050-01-01']);rejects(fn()=>$service->save($news['id'],$news['version'],$sections),InvalidArgumentException::class,'sections cannot silently turn another content kind into a page');
$model=new DataModel($db,$access);$template=$model->saveTemplate(['key'=>'sections_custom','label'=>'Sections custom','renderer'=>'standard','fields'=>[]]);$custom=$pages->save(['title'=>'Original custom','slug'=>'sections-custom','template'=>'sections_custom']);$model->saveTemplate(['key'=>'sections_custom','label'=>'Changed model','renderer'=>'standard','fields'=>[]],$template['version']);
rejects(fn()=>$service->save($custom['id'],$custom['version'],$sections),Conflict::class,'targeted section form cannot silently migrate original model');
$manager=new Manager($db,$access,$root,'csrf');rejects(fn()=>$manager->action('website',['operation'=>'page-sections-save','csrf'=>'wrong','id'=>$restored['id'],'version'=>(string)$restored['version'],'section_rows'=>$post],[]),DomainException::class,'section controller keeps CSRF guard');
$raw=Db::run($db,'SELECT draft_json FROM khcms_pages WHERE id=?',[$restored['id']])->fetchColumn();$db->beginTransaction();$service->save($restored['id'],$restored['version'],[]);$db->rollBack();check(Db::run($db,'SELECT draft_json FROM khcms_pages WHERE id=?',[$restored['id']])->fetchColumn()===$raw,'outer rollback preserves whole original collection');
check(hash_file('sha256',$media->variant($photo['id'],'original')['path'])===$bytes,'all collection operations preserve original stored photo bytes');
// Ordinary page edits carry the separate section collection and reject forged replacements.
$normal=$restored;$normal['operation']='page-save';$normal['csrf']='csrf';$normal['version']=(string)$restored['version'];$normal['content_sections']=[];
$manager->action('website',$normal,[]);$latest=$pages->get($restored['id']);check($latest['content_sections']===$sections,'ordinary page form retains separately saved sections despite forged replacement');
// The visible page form now saves its title, body and exact section collection in one revision.
$combined=$latest;$combined['operation']='page-save';$combined['csrf']='csrf';$combined['version']=(string)$latest['version'];$combined['title']='One common saved page';$combined['sections_present']='1';$combined['section_row_count']='2';$combined['section_rows']=[];
foreach($sections as $index=>$value){foreach($value as &$field)if(is_int($field))$field=(string)$field;unset($field);$value['media_id']??='';$combined['section_rows'][]=$value+['position'=>(string)(($index+1)*10)];}
$combined['section_rows'][0]['heading']='One common saved section';$revision=$latest['version'];$oldPublic=$pages->publicPage($latest['slug']);$manager->action('website',$combined,[]);$latest=$pages->get($latest['id']);
check($latest['version']===$revision+1&&$latest['title']==='One common saved page'&&$latest['content_sections'][0]['heading']==='One common saved section','same page form atomically saves text and sections in exactly one private revision');
check($pages->publicPage($latest['slug'])===$oldPublic,'common form retains exact prior publication');
rejects(fn()=>$manager->action('website',$combined,[]),Conflict::class,'stale common form cannot replace any page or section value');
