rejects(fn()=>$manager->action('website',$invalid,[]),InvalidArgumentException::class,'invalid section rejects the entire common page save');
check($pages->get($latest['id'])===$latest,'failed common save preserves every current page and section original');
$sections=$latest['content_sections'];
$trash=(new PageTrash($db,$access))->move($latest['id'],$latest['version']);rejects(fn()=>$service->save($trash['id'],$trash['version'],[]),Conflict::class,'trashed page cannot change section originals');
